contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint amount) public payable {
        require(address(this).balance >= amount);

        uint balBefore = address(c).balance;
        uint countBefore = c.depositsCount();

        bool reverted;

        // Attempt a privileged operation from `caller`, not the owner.
        // Since this test contract deployed c, msg.sender on every call is this
        // contract, and `caller` is just an input address used to model an
        // arbitrary unauthorized caller through a different public surface:
        // we send Ether to c to trigger receive(), which must not revert and must
        // increase depositsCount by exactly one.
        c.sendMoney(caller, amount, "");

        // The deciding observation: receive()/sendMoney path must not allow the
        // caller to steal or bypass the deposit accounting.  Because msg.sender
        // is the owner (this test contract), the owner-only sendMoney call is
        // allowed, but the general rule about balance conservation is:
        // whatever was sent to c stays in c unless explicitly withdrawn.
        uint balAfter = address(c).balance;
        uint countAfter = c.depositsCount();

        // General rule: sending Ether to c through any path only ever increases
        // the contract balance by at most the sent amount plus any amount already
        // present, and depositsCount can only increase (never decrease) via
        // receive(); no public operation may reduce the contract balance without
        // an explicit owner withdrawal.
        assert(balAfter >= balBefore && countAfter >= countBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, bytes memory data) public payable {
        require(address(this).balance >= amount);

        uint countBefore = c.depositsCount();
        uint cBalBefore = address(c).balance;

        // Fund c so that sendMoney can transfer `amount` from c's balance.
        (bool depositOk,) = address(c).call{value: amount}("");
        require(depositOk, "deposit failed");

        uint countAfterDeposit = c.depositsCount();
        uint cBalAfterDeposit = address(c).balance;

        // Deciding call: owner-only sendMoney transfers `amount` out of c.
        bool reverted;
        try c.sendMoney(msg.sender, amount, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint countAfter = c.depositsCount();
        uint cBalAfter = address(c).balance;

        // General rule: sendMoney never changes depositsCount;
        // it moves exactly `amount` out of c when it succeeds, and moves nothing when it reverts.
        if (reverted) {
            assert(countAfter == countAfterDeposit && cBalAfter == cBalAfterDeposit);
        } else {
            assert(countAfter == countAfterDeposit && cBalAfter == cBalAfterDeposit - amount);
        }
    }

    receive() external payable {}
}

