contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint valueToWithdraw, uint valueToSend, bytes memory data) public payable {
        require(msg.sender != c.owner(), "precondition: caller must not be the owner");
        require(address(this).balance >= valueToSend, "enough ether for sendMoney attempt");

        // Record the owner and the contract balance before any owner-only attempt.
        address ownerBefore = c.owner();
        uint balanceBefore = address(c).balance;

        // A non-owner's attempt to withdraw all must revert.
        bool withdrawAllReverted;
        try c.withdrawAll() { withdrawAllReverted = false; } catch { withdrawAllReverted = true; }

        // A non-owner's attempt to withdraw a chosen amount must revert.
        bool withdrawReverted;
        try c.withdraw(valueToWithdraw) { withdrawReverted = false; } catch { withdrawReverted = true; }

        // A non-owner's attempt to send Ether out must revert.
        bool sendMoneyReverted;
        try c.sendMoney{value: valueToSend}(target, valueToSend, data) { sendMoneyReverted = false; } catch { sendMoneyReverted = true; }

        // General rule: for any non-owner input, all three privilege-restricted calls must revert,
        // the owner must remain unchanged, and the contract balance must not decrease.
        assert(
            withdrawAllReverted &&
            withdrawReverted &&
            sendMoneyReverted &&
            c.owner() == ownerBefore &&
            address(c).balance >= balanceBefore
        );
    }
    receive() external payable {}
}

